using System.Text.Encodings.Web;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.AspNetCore.Razor.TagHelpers;

namespace ResortGuestbook.Web.TagHelpers;

/// <summary>
/// <c>&lt;icon name="search" class="h-5 w-5" /&gt;</c> renders a decorative Lucide icon from the versioned
/// <c>/icons.svg</c> sprite (generated by <c>build.mjs</c> from <c>Scripts/core/icon-set.js</c>).
/// </summary>
[HtmlTargetElement("icon", TagStructure = TagStructure.WithoutEndTag)]
public sealed class IconTagHelper(IFileVersionProvider versions) : TagHelper
{
    public string Name { get; set; } = string.Empty;

    [ViewContext]
    [HtmlAttributeNotBound]
    public ViewContext ViewContext { get; set; } = null!;

    public override void Process(TagHelperContext context, TagHelperOutput output)
    {
        output.TagName = "svg";
        output.TagMode = TagMode.StartTagAndEndTag;
        var classes = output.Attributes["class"]?.Value?.ToString();
        output.Attributes.SetAttribute("class", string.IsNullOrWhiteSpace(classes) ? "icon" : $"icon {classes}");
        output.Attributes.SetAttribute("aria-hidden", "true");
        output.Attributes.SetAttribute("focusable", "false");
        var sprite = versions.AddFileVersionToPath(ViewContext.HttpContext.Request.PathBase, "/icons.svg");
        output.Content.SetHtmlContent($"<use href=\"{HtmlEncoder.Default.Encode($"{sprite}#{Name}")}\"></use>");
    }
}
